    FrozenFilterCase("ISV", "thml", "Matt.1.1", 0, "<div class=\"title\">The Gospel According to Matthew</div><div class=\"sechead\">The Ancestry of Jesus Christ <scripRef>Luke 3:23-28</scripRef></div>This is<note>The Gk. lacks <i>This is</i></note> a record of the birth of Jesus Christ,<note>I.e. the Messiah</note> the son of David, the son of Abraham.<scripRef>Gen 12:3; 22:18; Ps 132:11; Isa 11:1; Jer 23:5; Matt 22:42; Luke 3:23; John 7:42; Acts 2:30; 13:23; Rom 1:3; Gal 3:16</scripRef><br />", "<div>The Gospel According to Matthew</div><div>The Ancestry of Jesus Christ <reference osisRef=\"Luke.3.23-Luke.3.28\">Luke 3:23-28</reference></div>This is<note type=\"x-StudyNote\">The Gk. lacks <hi type=\"italic\">This is</hi></note> a record of the birth of Jesus Christ,<note type=\"x-StudyNote\">I.e. the Messiah</note> the son of David, the son of Abraham.<reference osisRef=\"Gen.12.3 Gen.22.18 Ps.132.11 Isa.11.1 Jer.23.5 Matt.22.42 Luke.3.23 John.7.42 Acts.2.30 Acts.13.23 Rom.1.3 Gal.3.16\">Gen 12:3; 22:18; Ps 132:11; Isa 11:1; Jer 23:5; Matt 22:42; Luke 3:23; John 7:42; Acts 2:30; 13:23; Rom 1:3; Gal 3:16</reference><lb />"),
    FrozenFilterCase("ISV", "thml", "Matt.1.4", 0, "Aram fathered Aminidab, Aminidab fathered Nahshon, and Nahshon fathered Salmon.", "Aram fathered Aminidab, Aminidab fathered Nahshon, and Nahshon fathered Salmon."),
    FrozenFilterCase("ISV", "thml", "Matt.1.7", 0, "Solomon fathered Rehoboam, Rehoboam fathered Abijah, Abijah fathered Asaph,<note>Other mss. read <i>Asa</i></note><scripRef>1Chr 3:10</scripRef>", "Solomon fathered Rehoboam, Rehoboam fathered Abijah, Abijah fathered Asaph,<note type=\"x-StudyNote\">Other mss. read <hi type=\"italic\">Asa</hi></note><reference osisRef=\"1Chr.3.10\">1Chr 3:10</reference>"),
    FrozenFilterCase("ISV", "thml", "Matt.1.10", 0, "Hezekiah fathered Manasseh, Manasseh fathered Amos,<note>Other mss. read <i>Amon</i></note> and Amos<note>Other mss. read <i>Amon</i></note> fathered Josiah.<scripRef>2Kings 20:21; 1Chr 3:13</scripRef>", "Hezekiah fathered Manasseh, Manasseh fathered Amos,<note type=\"x-StudyNote\">Other mss. read <hi type=\"italic\">Amon</hi></note> and Amos<note type=\"x-StudyNote\">Other mss. read <hi type=\"italic\">Amon</hi></note> fathered Josiah.<reference osisRef=\"2Kgs.20.21 1Chr.3.13\">2Kings 20:21; 1Chr 3:13</reference>"),
    FrozenFilterCase("ISV", "thml", "Matt.1.13", 0, "Zerubbabel fathered Abiud, Abiud fathered Eliakim, Eliakim fathered Azor,", "Zerubbabel fathered Abiud, Abiud fathered Eliakim, Eliakim fathered Azor,"),
    FrozenFilterCase("ISV", "thml", "Matt.1.16", 0, "Jacob fathered Joseph, the husband of Mary, who was the mother of Jesus,<note>Lit. <i>of whom Jesus was born</i></note> who is called the Christ.<note>I.e. the Messiah</note><br />", "Jacob fathered Joseph, the husband of Mary, who was the mother of Jesus,<note type=\"x-StudyNote\">Lit. <hi type=\"italic\">of whom Jesus was born</hi></note> who is called the Christ.<note type=\"x-StudyNote\">I.e. the Messiah</note><lb />"),
    FrozenFilterCase("ISV", "thml", "Matt.1.19", 0, "Her husband Joseph, being a righteous man and unwilling to disgrace her, decided to divorce her secretly.<scripRef>Deut 24:1</scripRef><br />", "Her husband Joseph, being a righteous man and unwilling to disgrace her, decided to divorce her secretly.<reference osisRef=\"Deut.24.1\">Deut 24:1</reference><lb />"),
    FrozenFilterCase("ISV", "thml", "Matt.1.22", 0, "Now all this happened to fulfill what was declared by the Lord through the prophet when he said,<br />", "Now all this happened to fulfill what was declared by the Lord through the prophet when he said,<lb />"),
    FrozenFilterCase("ISV", "thml", "Matt.1.25", 0, "He did not have marital relations with<note>Lit. <i>did not know</i></note> her until she had given birth to a son;<note>Other mss. read <i>to her firstborn son</i></note> and he named him Jesus.<scripRef>Exod 13:2; Luke 2:7, 21</scripRef><br />", "He did not have marital relations with<note type=\"x-StudyNote\">Lit. <hi type=\"italic\">did not know</hi></note> her until she had given birth to a son;<note type=\"x-StudyNote\">Other mss. read <hi type=\"italic\">to her firstborn son</hi></note> and he named him Jesus.<reference osisRef=\"Exod.13.2 Luke.2.7 Luke.2.21\">Exod 13:2; Luke 2:7, 21</reference><lb />"),
    // FinPR: inputs SHA-256 910820742eb00b2cb5071c27f0cc4d81b8afa913c85dca558406231f98fc31dc
    // FinPR: output SHA-256 511ae00dda16831eb27367ceae409dac32491b0ebfdacc7edf61c61d989b505c
    FrozenFilterCase("FinPR", "gbf", "Gen.1.1", 0, "Alussa loi Jumala taivaan ja maan.", "Alussa loi Jumala taivaan ja maan."),
    FrozenFilterCase("FinPR", "gbf", "Gen.1.12", 0, "maa tuotti vihantaa, ruohoja, jotka tekiv\u00e4t siement\u00e4 lajiensa mukaan, ja puita, jotka lajiensa mukaan kantoivat hedelm\u00e4\u00e4, jossa niiden siemen oli. Ja Jumala n\u00e4ki, ett\u00e4 se oli hyv\u00e4.", "maa tuotti vihantaa, ruohoja, jotka tekiv\u00e4t siement\u00e4 lajiensa mukaan, ja puita, jotka lajiensa mukaan kantoivat hedelm\u00e4\u00e4, jossa niiden siemen oli. Ja Jumala n\u00e4ki, ett\u00e4 se oli hyv\u00e4."),
    FrozenFilterCase("FinPR", "gbf", "Gen.1.23", 0, "Ja tuli ehtoo, ja tuli aamu, viides p\u00e4iv\u00e4.<CM>", "Ja tuli ehtoo, ja tuli aamu, viides p\u00e4iv\u00e4.<p />"),
    FrozenFilterCase("FinPR", "gbf", "Gen.2.3", 0, "Ja Jumala siunasi seitsem\u00e4nnen p\u00e4iv\u00e4n ja pyhitti sen, koska h\u00e4n sin\u00e4 p\u00e4iv\u00e4n\u00e4 lep\u00e4si kaikesta luomisty\u00f6st\u00e4ns\u00e4, jonka h\u00e4n oli tehnyt.<CM>", "Ja Jumala siunasi seitsem\u00e4nnen p\u00e4iv\u00e4n ja pyhitti sen, koska h\u00e4n sin\u00e4 p\u00e4iv\u00e4n\u00e4 lep\u00e4si kaikesta luomisty\u00f6st\u00e4ns\u00e4, jonka h\u00e4n oli tehnyt.<p />"),
    FrozenFilterCase("FinPR", "gbf", "Gen.2.14", 0, "Kolmannen virran nimi on Hiddekel; se juoksee Assurin editse. Ja nelj\u00e4s virta on Eufrat.", "Kolmannen virran nimi on Hiddekel; se juoksee Assurin editse. Ja nelj\u00e4s virta on Eufrat."),
    FrozenFilterCase("FinPR", "gbf", "Gen.2.25", 0, "Ja he olivat molemmat, mies ja h\u00e4nen vaimonsa, alasti eiv\u00e4tk\u00e4 h\u00e4venneet toisiansa.<CM>", "Ja he olivat molemmat, mies ja h\u00e4nen vaimonsa, alasti eiv\u00e4tk\u00e4 h\u00e4venneet toisiansa.<p />"),
    FrozenFilterCase("FinPR", "gbf", "Gen.3.11", 0, "Ja h\u00e4n sanoi: \"Kuka sinulle ilmoitti, ett\u00e4 olet alasti? Etk\u00f6 sy\u00f6nyt siit\u00e4 puusta, josta min\u00e4 kielsin sinua sy\u00f6m\u00e4st\u00e4?\"", "Ja h\u00e4n sanoi: &amp;quot;Kuka sinulle ilmoitti, ett\u00e4 olet alasti? Etk\u00f6 sy\u00f6nyt siit\u00e4 puusta, josta min\u00e4 kielsin sinua sy\u00f6m\u00e4st\u00e4?&amp;quot;"),
    FrozenFilterCase("FinPR", "gbf", "Gen.3.22", 0, "Ja Herra Jumala sanoi: \"Katso, ihminen on tullut sellaiseksi kuin joku meist\u00e4, niin ett\u00e4 h\u00e4n tiet\u00e4\u00e4 hyv\u00e4n ja pahan. Kun ei h\u00e4n nyt vain ojentaisi k\u00e4tt\u00e4ns\u00e4 ja ottaisi my\u00f6s el\u00e4m\u00e4n puusta ja s\u00f6isi ja el\u00e4isi iankaikkisesti!\"", "Ja Herra Jumala sanoi: &amp;quot;Katso, ihminen on tullut sellaiseksi kuin joku meist\u00e4, niin ett\u00e4 h\u00e4n tiet\u00e4\u00e4 hyv\u00e4n ja pahan. Kun ei h\u00e4n nyt vain ojentaisi k\u00e4tt\u00e4ns\u00e4 ja ottaisi my\u00f6s el\u00e4m\u00e4n puusta ja s\u00f6isi ja el\u00e4isi iankaikkisesti!&amp;quot;"),
    FrozenFilterCase("FinPR", "gbf", "Gen.4.9", 0, "Niin Herra sanoi Kainille: \"Miss\u00e4 on veljesi Aabel?\" H\u00e4n vastasi: \"En tied\u00e4; olenko min\u00e4 veljeni vartija?\"", "Niin Herra sanoi Kainille: &amp;quot;Miss\u00e4 on veljesi Aabel?&amp;quot; H\u00e4n vastasi: &amp;quot;En tied\u00e4; olenko min\u00e4 veljeni vartija?&amp;quot;"),
    FrozenFilterCase("FinPR", "gbf", "Gen.4.20", 0, "Ja Aada synnytti Jaabalin; h\u00e4nest\u00e4 tuli niiden kantais\u00e4, jotka teltoissa asuvat ja karjanhoitoa harjoittavat.", "Ja Aada synnytti Jaabalin; h\u00e4nest\u00e4 tuli niiden kantais\u00e4, jotka teltoissa asuvat ja karjanhoitoa harjoittavat."),
    // StrongsGreek: inputs SHA-256 1c6c82f0fa568331a9fcf7347178817b95ccfe6370a8e4f6178fd0c957a0da8d
    // StrongsGreek: output SHA-256 922718be80d1f388bb07f82f50a2e7551854b4ead227280118963f4e43d634d9
    FrozenFilterCase("StrongsGreek", "plaintext", "               Dictionaries of Hebrew and Greek Words", 0, "Dictionaries of Hebrew and Greek Words\r\n                             taken from\r\n                  Strong's Exhaustive Concordance\r\n                                 by\r\n                    James Strong, S.T.D., LL.D. \r\n                                1890\r\n\r\n                   Public Domain -- Copy Freely\r\n\r\nFor a hundred years Strong's Dictionaries have been popular with Bible students.\r\nBy assigning numbers to each unique word in the Old and New Testaments and\r\nlisting each word with its number, Strong produced a standard, still used today,\r\nfor referencing definitions. Bible students, with little or no knowledge of\r\nGreek and Hebrew, are able to use Strong's numbers to learn about the Greek and\r\nHebrew of the Bible.\r\n\r\nASCII e-text version:\r\n=====================\r\n\r\nThe files for this e-text were produced by Michael Grier, mgrier@pdnt.com,\r\nin 1996, and download from  http://members.tripod.com/~SoftIdeas, in\r\nFebruary 1998. The files have been setup for importing into the Online\r\nBible for DOS. But to make these files into generic text files, all that\r\nis needed is to replace the terms \"GREEK\" and \"HEBREW\" with \"Greek\" and\r\n\"Hebrew\" or the names of the appropriate files. \r\n\r\nThe e-text has been changed from the printed version in three ways.\r\n\r\n1) A five digit Strong's word number with leading zeros has been placed before\r\n   each entry. \r\n2) Where Strong provides the number of another word for etymology,\r\n   a line with \"see GREEK for\" or \"see HEBREW for\" and the number, has been\r\n   added after Strong's entry for the word. (This is for use after\r\n   importing into the DOS version of Online Bible, but also provides a good\r\n   way to programmatically add links.)\r\n3) The abbreviations used by Strong in the\r\n   Greek dictionary, (not Hebrew) have been replaced by the abbreviated words.\r\n\r\nMichael Grier did a check of the e-text against a printed Strong's dictionary.\r\nThe work seems clean but more proofreading is needed to certify it clean from\r\nerrors.\r\n\r\nFurther info:\r\n=============\r\n\r\nIf you are looking for Strong's that will self install into the Online\r\nBible see:\r\n           Michael Grier\r\n           mgrier@pdnt.com\r\n           http://members.tripod.com/~SoftIdeas\r\n\r\nIf any errors are located, please ensure you have the latest files,\r\nand if so, we would appreciate being informed of the error.\r\n\r\n           Bible Foundation\r\n           bf@bf.org\r\n           http://www.bf.org/\r\n           or the e-text Library\r\n           http://www.bf.org/bfetexts.htm", "Dictionaries of Hebrew and Greek Words&#xD;<lb />                             taken from&#xD;<lb />                  Strong's Exhaustive Concordance&#xD;<lb />                                 by&#xD;<lb />                    James Strong, S.T.D., LL.D. &#xD;<lb />                                1890&#xD;<lb />&#xD;<lb />                   Public Domain -- Copy Freely&#xD;<lb />&#xD;<lb />For a hundred years Strong's Dictionaries have been popular with Bible students.&#xD;<lb />By assigning numbers to each unique word in the Old and New Testaments and&#xD;<lb />listing each word with its number, Strong produced a standard, still used today,&#xD;<lb />for referencing definitions. Bible students, with little or no knowledge of&#xD;<lb />Greek and Hebrew, are able to use Strong's numbers to learn about the Greek and&#xD;<lb />Hebrew of the Bible.&#xD;<lb />&#xD;<lb />ASCII e-text version:&#xD;<lb />=====================&#xD;<lb />&#xD;<lb />The files for this e-text were produced by Michael Grier, mgrier@pdnt.com,&#xD;<lb />in 1996, and download from  http://members.tripod.com/~SoftIdeas, in&#xD;<lb />February 1998. The files have been setup for importing into the Online&#xD;<lb />Bible for DOS. But to make these files into generic text files, all that&#xD;<lb />is needed is to replace the terms \"GREEK\" and \"HEBREW\" with \"Greek\" and&#xD;<lb />\"Hebrew\" or the names of the appropriate files. &#xD;<lb />&#xD;<lb />The e-text has been changed from the printed version in three ways.&#xD;<lb />&#xD;<lb />1) A five digit Strong's word number with leading zeros has been placed before&#xD;<lb />   each entry. &#xD;<lb />2) Where Strong provides the number of another word for etymology,&#xD;<lb />   a line with \"see GREEK for\" or \"see HEBREW for\" and the number, has been&#xD;<lb />   added after Strong's entry for the word. (This is for use after&#xD;<lb />   importing into the DOS version of Online Bible, but also provides a good&#xD;<lb />   way to programmatically add links.)&#xD;<lb />3) The abbreviations used by Strong in the&#xD;<lb />   Greek dictionary, (not Hebrew) have been replaced by the abbreviated words.&#xD;<lb />&#xD;<lb />Michael Grier did a check of the e-text against a printed Strong's dictionary.&#xD;<lb />The work seems clean but more proofreading is needed to certify it clean from&#xD;<lb />errors.&#xD;<lb />&#xD;<lb />Further info:&#xD;<lb />=============&#xD;<lb />&#xD;<lb />If you are looking for Strong's that will self install into the Online&#xD;<lb />Bible see:&#xD;<lb />           Michael Grier&#xD;<lb />           mgrier@pdnt.com&#xD;<lb />           http://members.tripod.com/~SoftIdeas&#xD;<lb />&#xD;<lb />If any errors are located, please ensure you have the latest files,&#xD;<lb />and if so, we would appreciate being informed of the error.&#xD;<lb />&#xD;<lb />           Bible Foundation&#xD;<lb />           bf@bf.org&#xD;<lb />           http://www.bf.org/&#xD;<lb />           or the e-text Library&#xD;<lb />           http://www.bf.org/bfetexts.htm"),
    FrozenFilterCase("StrongsGreek", "plaintext", "00002", 0, "00002\\\n 2  Aaron  ah-ar-ohn'\r\n\r\n of Hebrew origin (175); Aaron, the brother of Moses:--Aaron.\r\n see HEBREW for 0175", "00002\\<lb /> 2  Aaron  ah-ar-ohn'&#xD;<lb />&#xD;<lb /> of Hebrew origin (175); Aaron, the brother of Moses:--Aaron.&#xD;<lb /> see HEBREW for 0175"),
