    FrozenFilterCase("StrongsGreek", "plaintext", "00012", 0, "00012\\\n 12  abussos  ab'-us-sos\r\n\r\n from 1 (as a negative particle) and a variation of 1037; depthless,\r\n i.e. (specially) (infernal) \"abyss\":--deep, (bottomless) pit.\r\n see GREEK for 1\r\n see GREEK for 1037", "00012\\<lb /> 12  abussos  ab'-us-sos&#xD;<lb />&#xD;<lb /> from 1 (as a negative particle) and a variation of 1037; depthless,&#xD;<lb /> i.e. (specially) (infernal) \"abyss\":--deep, (bottomless) pit.&#xD;<lb /> see GREEK for 1&#xD;<lb /> see GREEK for 1037"),
